exercises.solution:
def autoriser(roles, utilisateurs, nom, action):
    for role in utilisateurs.get(nom, []):
        if action in roles.get(role, []):
            return True
    return False

def conflits(roles, utilisateurs, paires):
    noms = []
    for nom, liste in utilisateurs.items():
        droits = set()
        for role in liste:
            droits |= set(roles.get(role, []))
        if any(a in droits and b in droits for a, b in paires):
            noms.append(nom)
    return sorted(noms)
